import { Button, Stack, Typography } from '@mui/material'
import type { ReactNode } from 'react'
import { hasActionRunBackend } from '../data/electron_action_bridge'
import { AgentChatFab } from './agents/agent_chat_fab'
import { useProjectReference } from './hooks/use_project_reference'
import { requestOpenProjectDialog } from './project_command_events'

interface ProjectWorkspaceAvailabilityProps {
    children: ReactNode
}

function openProjectDialog() {
    requestOpenProjectDialog()
}

/** Show project workspace content only while a project is open. */
export function ProjectWorkspaceAvailability({ children }: ProjectWorkspaceAvailabilityProps) {
    const project = useProjectReference()

    if (project) return <>{children}{hasActionRunBackend() ? <AgentChatFab /> : null}</>

    return (
        <Stack
            spacing={2}
            sx={{ alignItems: 'center', flex: 1, justifyContent: 'center', px: 3, textAlign: 'center' }}
        >
            <Typography component="h2" variant="h6">No project open</Typography>
            <Typography color="text.secondary" variant="body2">
                Open a GitHub repository or local folder to work with project cards.
            </Typography>
            <Button onClick={openProjectDialog} variant="contained">Open project...</Button>
        </Stack>
    )
}

import { Box } from '@mui/material'
import type { ReactNode } from 'react'
import { useEffect, useRef } from 'react'
import { dialogService } from '../../services/dialog_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'

interface MobileLayoutProps {
    content: ReactNode
}

/** Mobile body layout: a single panel that is only visible while the text view mode is active. */
export function MobileLayout(props: MobileLayoutProps) {
    const { content } = props
    const containerRef = useRef<HTMLDivElement>(null)
    const missingContainerReportedRef = useRef(false)

    useEffect(() => {
        const updateVisibility = () => {
            const container = containerRef.current
            if (!container) {
                if (!missingContainerReportedRef.current) {
                    missingContainerReportedRef.current = true
                    dialogService.error(new Error('Missing mobile layout container'), {fallbackMessage: 'Mobile layout could not be displayed'})
                }
                return
            }

            container.style.display = workspaceViewService.getSnapshot().viewMode === 'text' ? 'flex' : 'none'
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [])

    return (
        <Box ref={containerRef} sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'auto' }}>
            <Box sx={{ flex: 1, minWidth: 0, overflow: 'auto' }}>
                {content}
            </Box>
        </Box>
    )
}

